-- 201_status_merge_parents_viewas.sql — the Verified status image, merging
-- duplicate accounts, Follow-ups → Parents and "View as" (owner, 26 Oct 2026).
-- Generated by scripts/build-migration-201.ts (the template bodies are the
-- code's own defaults). Additive: no existing row changes; nothing is deleted.
--
--   1. tutor_profiles.status_card_dismissed_at — the tutor dismissed the
--      one-time "You're verified! Share it on your status" card.
--   2. member_follow_ups.source may also be 'status_image' and 'parents'.
--   3. Templates: status_image_verified (never a link) and the five
--      Follow-ups → Parents messages. Inserted only when missing.
--   4. member_duplicate_dismissals — "Not a duplicate": a pair, hidden for good.
--   5. profiles.merged_into / merged_at / secondary_phone — "Merged into <name>"
--      and the other account's phone kept as a secondary contact. Members are
--      not granted UPDATE on these columns (profiles UPDATE is column-level).
--   6. member_merges — every merge, its full log of moved records (for an exact
--      Undo), who and when.
--   7. member_notes_guard — a note may move between the two accounts of a merge
--      (the service role only); everything else about a note stays locked.
--   8. merged_tutor_redirects() — the merged tutor's slug and the kept one's,
--      for the proxy's 301. Nothing else.
--   9. view_as_sessions + is_view_as_session() + end_view_as_session() — the
--      sessions minted for "View as", so the database refuses every write made
--      with one, and the session can be removed when the view ends.
--  10. RESTRICTIVE policies on every public table with RLS, and on
--      storage.objects: no insert, update or delete by a View-as session.

-- 1 ------------------------------------------------------------------------
alter table public.tutor_profiles add column if not exists status_card_dismissed_at timestamptz;

-- 2 ------------------------------------------------------------------------
alter table public.member_follow_ups drop constraint if exists member_follow_ups_source_check;
alter table public.member_follow_ups
  add constraint member_follow_ups_source_check check (source in ('stuck', 'unpaid', 'abandoned', 'documents', 'status_image', 'parents'));

-- 3 ------------------------------------------------------------------------
insert into public.admin_message_templates (key, title, subject, body)
values
  (E'status_image_verified', E'Status image — you are a Verified Tutor', E'You are a Verified Tutor',
   E'Congratulations {tutor_first_name}, you\'re now a Verified Tutor on TutorMint ✓ Please post this on your WhatsApp status.'),
  (E'pf_no_tuition', E'Parents — signed up, no tuition posted', E'Signed up, no tuition posted',
   E'Assalam o Alaikum {first_name}, thank you for joining TutorMint. Posting a tuition is free: tell us the class, subjects and area, and verified tutors can apply.\nYou can post it here:\n{post_link}\n\nNeed help? WhatsApp us on {support_whatsapp}'),
  (E'pf_no_applicants', E'Parents — tuition posted, no applicants', E'Tuition posted, no applicants',
   E'Assalam o Alaikum {first_name}, your tuition "{tuition_title}" is live on TutorMint, but no tutor has applied yet. Adding timings and more detail helps tutors decide.\nYou can see it here:\n{tuition_link}\n\nNeed help? WhatsApp us on {support_whatsapp}'),
  (E'pf_email_unconfirmed', E'Parents — email not confirmed', E'Email not confirmed',
   E'Assalam o Alaikum {first_name}, thank you for signing up to TutorMint. Please open the email we sent you and tap the link to confirm your address. If it is not in your inbox, check your spam folder.\n\nNeed help? WhatsApp us on {support_whatsapp}'),
  (E'pf_expired', E'Parents — tuition ended, still looking?', E'Tuition ended, still looking?',
   E'Assalam o Alaikum {first_name}, your tuition "{tuition_title}" is no longer live on TutorMint. Still looking? We can repost it — just reply to this message.\n\nNeed help? WhatsApp us on {support_whatsapp}'),
  (E'pf_hired', E'Parents — tutor hired, thanks', E'Tutor hired, thanks',
   E'Assalam o Alaikum {first_name}, thank you for hiring {tutor_name} through TutorMint. We hope the lessons go well. Could you reply with a short review of the tutor? It helps other parents.\n\nNeed help? WhatsApp us on {support_whatsapp}')
on conflict (key) do nothing;

-- 4 ------------------------------------------------------------------------
create table if not exists public.member_duplicate_dismissals (
  a_id uuid not null references public.profiles (id) on delete cascade,
  b_id uuid not null references public.profiles (id) on delete cascade,
  dismissed_by uuid references public.profiles (id) on delete set null,
  dismissed_at timestamptz not null default now(),
  primary key (a_id, b_id),
  check (a_id < b_id)
);
alter table public.member_duplicate_dismissals enable row level security;
drop policy if exists member_duplicate_dismissals_admin_read on public.member_duplicate_dismissals;
create policy member_duplicate_dismissals_admin_read on public.member_duplicate_dismissals for select to authenticated using (public.is_admin());

-- 5 ------------------------------------------------------------------------
alter table public.profiles add column if not exists merged_into uuid references public.profiles (id) on delete set null;
alter table public.profiles add column if not exists merged_at timestamptz;
alter table public.profiles add column if not exists secondary_phone text;
create index if not exists profiles_merged_into_idx on public.profiles (merged_into) where merged_into is not null;

-- 6 ------------------------------------------------------------------------
create table if not exists public.member_merges (
  id uuid primary key default gen_random_uuid(),
  kept_id uuid not null references public.profiles (id) on delete cascade,
  merged_id uuid not null references public.profiles (id) on delete cascade,
  merged_by uuid references public.profiles (id) on delete set null,
  created_at timestamptz not null default now(),
  status text not null default 'applying' check (status in ('applying', 'done', 'failed')),
  error text,
  log jsonb not null default '{}'::jsonb,
  undone_at timestamptz,
  undone_by uuid references public.profiles (id) on delete set null,
  check (kept_id <> merged_id)
);
create index if not exists member_merges_kept_idx on public.member_merges (kept_id);
create index if not exists member_merges_merged_idx on public.member_merges (merged_id);
alter table public.member_merges enable row level security;
drop policy if exists member_merges_admin_read on public.member_merges;
create policy member_merges_admin_read on public.member_merges for select to authenticated using (public.is_admin());

-- 7 ------------------------------------------------------------------------
create or replace function public.member_notes_guard()
returns trigger
language plpgsql
as $$
declare
  moved boolean := false;
begin
  if tg_op = 'DELETE' then
    -- A direct delete is refused. A cascade from deleting the member's account
    -- (the owner's junk cleanup) runs one trigger level deeper and is allowed.
    if pg_trigger_depth() <= 1 then
      raise exception 'member notes are never deleted; withdraw the note instead' using errcode = '42501';
    end if;
    return old;
  end if;
  -- A merge (owner, 26 Oct 2026) moves a note between the two accounts of a
  -- recorded merge — the service role only, and nothing else about the note.
  if new.member_id is distinct from old.member_id
     and coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'role', current_user) in ('service_role', 'postgres')
     and exists (
       select 1 from public.member_merges m
       where (m.kept_id = new.member_id and m.merged_id = old.member_id)
          or (m.kept_id = old.member_id and m.merged_id = new.member_id)
     ) then
    moved := true;
  end if;
  if (new.member_id is distinct from old.member_id and not moved)
     or new.kind is distinct from old.kind
     or new.body is distinct from old.body
     or new.staff_id is distinct from old.staff_id
     or new.staff_name is distinct from old.staff_name
     or new.created_at is distinct from old.created_at then
    raise exception 'a member note cannot be edited; withdraw it instead' using errcode = '42501';
  end if;
  if old.withdrawn_at is not null and (
       new.withdrawn_at is distinct from old.withdrawn_at
       or new.withdrawn_reason is distinct from old.withdrawn_reason
       or new.withdrawn_by is distinct from old.withdrawn_by) then
    raise exception 'this note was already withdrawn' using errcode = '42501';
  end if;
  if new.withdrawn_at is not null and new.withdrawn_reason is null then
    raise exception 'a withdrawn note needs a reason' using errcode = '23514';
  end if;
  return new;
end;
$$;

-- 8 ------------------------------------------------------------------------
create or replace function public.merged_tutor_redirects()
returns table (slug text, kept_slug text)
language sql
stable
security definer
set search_path = public
as $$
  select tp.slug, kt.slug
  from public.profiles p
  join public.tutor_profiles tp on tp.id = p.id
  join public.tutor_profiles kt on kt.id = p.merged_into
  where p.merged_into is not null and tp.slug is not null and kt.slug is not null
$$;
revoke all on function public.merged_tutor_redirects() from public;
grant execute on function public.merged_tutor_redirects() to anon, authenticated, service_role;

-- 9 ------------------------------------------------------------------------
create table if not exists public.view_as_sessions (
  id uuid primary key default gen_random_uuid(),
  owner_id uuid not null references public.profiles (id) on delete cascade,
  member_id uuid not null references public.profiles (id) on delete cascade,
  session_id uuid not null unique,
  started_at timestamptz not null default now(),
  expires_at timestamptz not null,
  ended_at timestamptz,
  end_reason text check (end_reason is null or end_reason in ('exit', 'expired', 'failed'))
);
alter table public.view_as_sessions enable row level security;
drop policy if exists view_as_sessions_admin_read on public.view_as_sessions;
create policy view_as_sessions_admin_read on public.view_as_sessions for select to authenticated using (public.is_admin());

create or replace function public.is_view_as_session()
returns boolean
language sql
stable
security definer
set search_path = public
as $$
  select exists (
    select 1 from public.view_as_sessions v
    where v.session_id = nullif(coalesce(current_setting('request.jwt.claims', true)::jsonb ->> 'session_id', ''), '')::uuid
  )
$$;
revoke all on function public.is_view_as_session() from public;
grant execute on function public.is_view_as_session() to anon, authenticated, service_role;

create or replace function public.end_view_as_session(p_session_id uuid)
returns void
language sql
security definer
set search_path = public, auth
as $$
  delete from auth.sessions s
  where s.id = p_session_id
    and exists (select 1 from public.view_as_sessions v where v.session_id = p_session_id)
$$;
revoke all on function public.end_view_as_session(uuid) from public, anon, authenticated;
grant execute on function public.end_view_as_session(uuid) to service_role;

-- 10 -----------------------------------------------------------------------
do $$
declare
  t record;
begin
  for t in select tablename from pg_tables where schemaname = 'public' and rowsecurity loop
    execute format('drop policy if exists view_as_no_insert on public.%I', t.tablename);
    execute format('drop policy if exists view_as_no_update on public.%I', t.tablename);
    execute format('drop policy if exists view_as_no_delete on public.%I', t.tablename);
    execute format('create policy view_as_no_insert on public.%I as restrictive for insert to authenticated with check (not (select public.is_view_as_session()))', t.tablename);
    execute format('create policy view_as_no_update on public.%I as restrictive for update to authenticated using (not (select public.is_view_as_session())) with check (not (select public.is_view_as_session()))', t.tablename);
    execute format('create policy view_as_no_delete on public.%I as restrictive for delete to authenticated using (not (select public.is_view_as_session()))', t.tablename);
  end loop;
end $$;

drop policy if exists view_as_no_insert on storage.objects;
drop policy if exists view_as_no_update on storage.objects;
drop policy if exists view_as_no_delete on storage.objects;
create policy view_as_no_insert on storage.objects as restrictive for insert to authenticated with check (not (select public.is_view_as_session()));
create policy view_as_no_update on storage.objects as restrictive for update to authenticated using (not (select public.is_view_as_session())) with check (not (select public.is_view_as_session()));
create policy view_as_no_delete on storage.objects as restrictive for delete to authenticated using (not (select public.is_view_as_session()));
